    private fun r(kind: Char, inflected: String, deinflected: String, conditionsIn: String, conditionsOut: String) =
        RuleDef(
            wholeWord = kind == 'W',
            inflected = inflected,
            deinflected = deinflected,
            conditionsIn = conditionsIn.split(' ').filter { it.isNotEmpty() },
            conditionsOut = conditionsOut.split(' ').filter { it.isNotEmpty() },
        )
}
